import csv, io, json, os, sys
from collections import Counter


def norm_id(s):
    return str(s).strip().lower()


def norm_text(s):
    s = s.casefold()
    s = "".join(c if c.isalnum() else " " for c in s)
    return " ".join(s.split())


def read_batches(cvr):
    files = []
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p):
            continue
        if name.endswith(".csv"):
            files.append(read_csv(p))
        elif name.endswith(".jsonl"):
            files.append(read_jsonl(p))
    best = {}
    for meta, recs in files:
        b = meta["batch"]
        rev = int(str(meta["revision"]).strip())
        if b not in best or rev > best[b][0]:
            best[b] = (rev, meta, recs)
    out = []
    for b in sorted(best, key=str):
        rev, meta, recs = best[b]
        if str(meta.get("status", "final")).strip().lower() == "void":
            continue
        out.extend(recs)
    return out


def read_csv(p):
    with open(p, encoding="utf-8-sig", newline="") as f:
        text = f.read()
    lines = text.split("\n")
    meta = {}
    i = 0
    while i < len(lines) and (lines[i].startswith("#") or not lines[i].strip()):
        l = lines[i]
        if l.startswith("#") and ":" in l:
            k, v = l[1:].split(":", 1)
            meta[k.strip().lower()] = v.strip()
        i += 1
    rows = csv.reader(io.StringIO("\n".join(lines[i:]), newline=""))
    header = None
    recs = []
    for row in rows:
        if not row or all(not c.strip() for c in row):
            continue
        if header is None:
            header = [c.strip() for c in row]
            continue
        d = dict(zip(header, row))
        ranks = {}
        for h, v in d.items():
            if h.startswith("rank") and h[4:].isdigit():
                n = int(h[4:])
                marks = [m for m in v.split("|")] if v != "" else []
                marks = [m for m in marks if m.strip() != "" or m.upper().startswith("WI:")]
                ranks[n] = [parse_mark(m) for m in marks]
        recs.append((d["contest"], ranks))
    return meta, recs


def parse_mark(m):
    if m[:3].upper() == "WI:":
        return ("w", m[3:])
    return ("c", norm_id(m))


def read_jsonl(p):
    meta = None
    recs = []
    with open(p, encoding="utf-8-sig") as f:
        for line in f:
            if not line.strip():
                continue
            o = json.loads(line)
            if meta is None:
                meta = o
                continue
            ranks = {}
            for m in o.get("marks", []):
                n = int(m["rank"])
                if m.get("write_in") is not None:
                    mk = ("w", m["write_in"])
                else:
                    mk = ("c", norm_id(m["candidate"]))
                ranks.setdefault(n, []).append(mk)
            recs.append((o["contest"], ranks))
    return meta, recs


def prepare(ranks, c):
    """Return tuple of rankings: ('s',), ('p',), ('o',), ('c', id)."""
    out = []
    seen = set()
    for n in range(1, c["max"] + 1):
        ids = []
        for kind, v in ranks.get(n, []):
            if kind == "w":
                v = c["wi"].get(norm_text(v))
                if v is None:
                    continue
            if v not in ids:
                ids.append(v)
        if not ids:
            out.append(("s",))
            continue
        ids = [x for x in ids if x not in c["withdrawn"]]
        if not ids:
            out.append(("p",))
            continue
        marked = set(ids)
        ids = [x for x in ids if x not in seen]
        seen |= marked
        if not ids:
            out.append(("s",))
        elif len(ids) == 1:
            out.append(("c", ids[0]))
        else:
            out.append(("o",))
    return tuple(out)


def read_ballot(r, cont):
    n = len(r)
    i = 0
    while i < n:
        k = r[i][0]
        if k == "c":
            if r[i][1] in cont:
                return r[i][1]
        elif k == "o":
            return None
        elif k == "s":
            if i + 1 >= n or r[i + 1][0] == "s":
                return None
        i += 1
    return None


def run(c, patterns, total):
    cont = set(c["order"])
    rounds = []
    hist = []
    winner = None
    while True:
        votes = {k: 0 for k in cont}
        active = 0
        for r, cnt in patterns.items():
            w = read_ballot(r, cont)
            if w is not None:
                votes[w] += cnt
                active += cnt
        rd = {"round": len(rounds) + 1,
              "tallies": {c["out"][k]: v for k, v in votes.items()},
              "exhausted": total - active, "eliminated": []}
        rounds.append(rd)
        hist.append(votes)
        if active == 0:
            break
        w = [k for k, v in votes.items() if v * 2 > active]
        if w:
            winner = w[0]
            break
        if len(cont) == 1:
            winner = next(iter(cont))
            break
        zeros = [k for k, v in votes.items() if v == 0]
        if zeros:
            el = zeros
        else:
            m = min(votes.values())
            tied = [k for k, v in votes.items() if v == m]
            for h in reversed(hist[:-1]):
                if len(tied) == 1:
                    break
                m2 = min(h[k] for k in tied)
                tied = [k for k in tied if h[k] == m2]
            if len(tied) > 1:
                tied = [max(tied, key=lambda k: c["lot"].get(k, -1))]
            el = tied
        rd["eliminated"] = sorted(c["out"][k] for k in el)
        cont -= set(el)
    return (c["out"][winner] if winner is not None else None), rounds


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, "election.json"), encoding="utf-8") as f:
        el = json.load(f)
    contests = {}
    for ct in el["contests"]:
        out = {}
        withdrawn = set()
        order = []
        for cd in ct.get("candidates", []):
            k = norm_id(cd["id"])
            out[k] = cd["id"]
            if cd.get("status", "active") == "withdrawn":
                withdrawn.add(k)
            else:
                order.append(k)
        wi = {}
        for w in ct.get("write_ins", []):
            k = norm_id(w["id"])
            out[k] = w["id"]
            order.append(k)
            for t in [w["name"]] + list(w.get("aliases", [])):
                wi.setdefault(norm_text(t), k)
        lot = {norm_id(x): i for i, x in enumerate(ct.get("lot_order", []))}
        contests[ct["id"]] = {"max": int(ct["max_ranks"]), "out": out,
                              "withdrawn": withdrawn, "order": order,
                              "wi": wi, "lot": lot,
                              "pat": Counter(), "n": 0}
    for cid, ranks in read_batches(os.path.join(inp, "cvr")):
        c = contests.get(cid)
        if c is None:
            continue
        c["pat"][prepare(ranks, c)] += 1
        c["n"] += 1
    res = {"election": el["election"], "contests": []}
    for ct in el["contests"]:
        c = contests[ct["id"]]
        w, rounds = run(c, c["pat"], c["n"])
        res["contests"].append({"contest": ct["id"], "ballots": c["n"],
                                "winner": w, "rounds": rounds})
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(res, f, ensure_ascii=False, indent=1)


main()
